arguments.new_str:
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<TicketModelTrainer>();

var app = builder.Build();

// Train the model at startup and register the prediction engine pool
var trainer = app.Services.GetRequiredService<TicketModelTrainer>();
var metrics = trainer.TrainAndEvaluate();

builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainer.ModelPath);

// Rebuild the service provider so the pool is available
var poolProvider = builder.Build();

app.MapGet("/metrics", () => Results.Ok(metrics));

app.MapPost("/predict", (TicketRequest request,
    PredictionEnginePool<TicketInput, TicketPrediction> pool) =>
{
    var input = new TicketInput
    {
        Subject = request.Subject,
        Description = request.Description,
        Priority = request.Priority,
    };

    var prediction = pool.Predict(input);

    var labels = new[] { "Billing", "General", "Technical" };
    var probabilities = labels.Zip(prediction.Score)
        .ToDictionary(p => p.First, p => p.Second);

    return Results.Ok(new TicketResponse
    {
        PredictedCategory = prediction.PredictedCategory,
        Probabilities = probabilities,
    });
});

app.Run();

